using System.Runtime.CompilerServices;

namespace Microsoft.ServiceFabric.Constants
{
    /// <summary>
    /// Provides compile-time constants describing Service Fabric assemblies.
    /// </summary>
    /// <remarks>
    /// This class is public to avoid having to list all Service Fabric assemblies using this project in <see cref="InternalsVisibleToAttribute"/>s.
    /// </remarks>
    public static class AssemblyInfo
    {
        /// <summary>
        /// Public key of the strong name signature of the assemblies we publish externally.
        /// </summary>
        /// <remarks>
        /// This key requires remote signing and projects using it produce delay-signed assemblies.
        /// Delay-signed assemblies cannot be loaded by .NET Framework unless unless strong name
        /// verification is disabled.
        /// </remarks>
        public const string PublicKey = ",";

        /// <summary>
        /// Public key of the strong name signature of the .NET Framework test assemblies.
        /// </summary>
        /// <remarks>
        /// <para>
        /// We don't use this key in this repository, only in the internal WindowsFabric repository.
        /// There, we fully-sign the .NET Framework test- and some product-assemblies presumably to avoid
        /// having to disable strong-name verification for each test assembly individually, or disabling
        /// verification of all assemblies signed with the <see cref="PublicKey"/> because that includes
        /// non-Service Fabric assemblies also signed by the same key by other product teams at Microsoft.
        /// </para>
        /// <para>
        /// We don't use this key to build the .NET Core test assemblies, because .NET doesn't verify strong names of assemblies.
        /// </para>
        /// </remarks>
        public const string TestKey = ",";

        /// <summary>
        /// Assembly generated by dynamic mocking frameworks based on Castle.Proxy, such as Moq and NSubstitute.
        /// </summary>
        public const string DynamicProxyGenAssembly2 = "DynamicProxyGenAssembly2, ";
    }
}
